def _enc_quad(root):
    """The same level order. The value of a node that is not a leaf does not
    matter, so it is always written as 1, as in LeetCode's examples."""
    out, queue, head = [], [root], 0
    while head < len(queue):
        if len(out) >= _MAX_NODES:
            raise RuntimeError("quad tree too large (cycle?)")
        n = queue[head]
        head += 1
        if n is None:
            out.append(None)
            continue
        out.append([1, 1 if n.val else 0] if n.isLeaf else [0, 1])
        queue.extend((n.topLeft, n.topRight, n.bottomLeft, n.bottomRight))
    while out and out[-1] is None:
        out.pop()
    return out


def _dec_multilevel(vals):
    """LeetCode's serialization: the levels one after the other, each ended
    by null, and each child level preceded by as many more nulls as its
    parent's index in the level above."""
    head, above, i = None, None, 0
    while i < len(vals):
        parent = None
        if above is not None:
            i += 1  # the null ending the level above
            k = 0
            while i < len(vals) and vals[i] is None:
                k += 1
                i += 1
            if i == len(vals):
                break
            if k >= len(above):
                raise InputError("a child level starts under node %d of a level with %d nodes" % (k + 1, len(above)))
            parent = above[k]
        level = []
        while i < len(vals) and vals[i] is not None:
            n = MultilevelNode(vals[i])
            if level:
                n.prev = level[-1]
                n.prev.next = n
            level.append(n)
            i += 1
        if not level:
            raise InputError("the list must start with a value")
        if parent is None:
            head = level[0]
        else:
            parent.child = level[0]
        above = level
    return head


