    """The same serialization. A prev pointer must point to the node before,
    and only one node of a level may have a child."""
    out, count, level = [], 0, head
    while level is not None:
        child, at, prev, n, i = None, 0, None, level, 0
        while n is not None:
            count += 1
            if count > _MAX_NODES:
                raise RuntimeError("list too long (cycle?)")
            if n.prev is not prev:
                if prev is None:
                    raise RuntimeError("node %d (val %r) starts a level but its prev pointer is not None" % (i, n.val))
                raise RuntimeError("the prev pointer of node %d (val %r) does not point to the node before it (val %r)" % (
                    i, n.val, prev.val))
            out.append(n.val)
            if n.child is not None:
                if child is not None:
                    raise RuntimeError("nodes %d and %d of a level both have a child; the multilevel format allows one per level" % (at, i))
                child, at = n.child, i
            prev, n, i = n, n.next, i + 1
        if child is not None:
            out.extend([None] * (at + 1))
        level = child
    return out


